<script>
  import { randomString } from '@splendidlabz/utils/dom'
  import { setContext } from 'svelte'
  import Accordion from '../Accordion/Accordion.svelte'
  import Tab from '../Tabs/Tab.svelte'
  import Tablist from '../Tabs/Tablist.svelte'
  import Tabpanel from '../Tabs/Tabpanel.svelte'
  import Tabpanels from '../Tabs/Tabpanels.svelte'
  import { getTab, selectTab } from '../Tabs/tabs.svelte.js'

  const {
    class: klass = '',
    breakpoint = 768,
    activeIndex: activeIndexProp = 0,
    accordion = {},
    tablist = {},
    tab = {},
    tabpanels = {},
    tabpanel = {},
    children,
    ...rest
  } = $props()

  const tabcordionId = randomString()
  const tabpanelsId = randomString()
  function getActiveIndexProp() {
    return activeIndexProp
  }

  let activeIndex = $state(getActiveIndexProp())
  const items = $state([])

  setContext('tabcordion', {
    register(item) {
      items.push(item)
      return items.length - 1
    },
  })

  $effect(() => {
    activeIndex = activeIndexProp
  })

  $effect(() => {
    const tabStore = getTab(tabpanelsId)
    if (!tabStore) return
    selectTab(tabStore, activeIndex, { shouldFocusOnTab: false })
  })

  function onTabChange({ Tab: tabStore }) {
    activeIndex = tabStore.state.activeTabIndex
  }
</script>

<!-- eslint-disable-next-line svelte/no-at-html-tags -->
{@html `
  <style>
    #${tabcordionId} .tabs { display: none; }

    @media (min-width: ${breakpoint}px) {
      #${tabcordionId} .accordion-stack { display: none; }
      #${tabcordionId} .tabs { display: block; }
    }
  </style>
`}

<!-- Render children purely for their registration side effect; they emit no DOM -->
{@render children?.()}

<div id={tabcordionId} {...rest} class="tabcordion {klass}">
  <div class="accordion-stack">
    {#each items as item, i (i)}
      <Accordion
        {...accordion}
        content={item.content}
        onToggle={() => (activeIndex = i)}
        open={i === activeIndex}
        title={item.title}
      />
    {/each}
  </div>

  <div class="tabs">
    <Tablist {...tablist} {onTabChange} target={tabpanelsId}>
      {#each items as item, i (i)}
        <Tab {...tab} active={i === activeIndex}>{@render item.title()}</Tab>
      {/each}
    </Tablist>
    <Tabpanels {...tabpanels} id={tabpanelsId}>
      {#each items as item, i (i)}
        <Tabpanel {...tabpanel} active={i === activeIndex}>
          {@render item.content()}
        </Tabpanel>
      {/each}
    </Tabpanels>
  </div>
</div>
